                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare by ASCII order
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1

        return 0

    def sort_key(version):
        version_nums, prerelease_identifiers = parse_version(version)
        return (version_nums, prerelease_identifiers is not None, prerelease_identifiers or [])

    # Stable sort using the parsed components
    parsed = [(version, parse_version(version)) for version in versions]

    # Sort by version numbers, then by prerelease status, then by prerelease identifiers
    def compare_full(item1, item2):
        version1, (nums1, pre1) = item1
        version2, (nums2, pre2) = item2

